tool_input.command:
mkdir -p "app/api/v3/api-keys/[apiKeyId]/rotate" app/api/v3/api-keys/lib
cat > app/api/v3/api-keys/lib/schemas.ts <<'EOF'
import { z } from "zod";

export const ZV3ApiKeyIdParams = z.object({ apiKeyId: z.cuid2() }).strict();

export type TV3ApiKeyIdParams = z.infer<typeof ZV3ApiKeyIdParams>;
EOF
cat > "app/api/v3/api-keys/[apiKeyId]/rotate/route.ts" <<'EOF'
/**
 * POST /api/v3/api-keys/{apiKeyId}/rotate - replace the key's secret, keeping its label and access
 * settings. The new plaintext key is in this response and nowhere else.
 */
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { rotateV3ApiKey } from "../../lib/operations";
import { ZV3ApiKeyIdParams } from "../../lib/schemas";

export const POST = withV3ApiWrapper({
  auth: "session",
  action: "updated",
  targetType: "apiKey",
  schemas: { params: ZV3ApiKeyIdParams },
  handler: async ({ authentication, parsedInput, auditLog, requestId, instance }) =>
    rotateV3ApiKey({
      authentication,
      apiKeyId: parsedInput.params.apiKeyId,
      auditLog,
      requestId,
      instance,
    }),
});
EOF
cat > app/api/v3/api-keys/lib/operations.ts <<'EOF'
import "server-only";
import { AuthorizationError, OperationNotAllowedError, ResourceNotFoundError } from "@formbricks/types/errors";
import { getV3SessionUserId } from "@/app/api/v3/lib/auth";
import { problemForbidden, problemUnauthorized, successResponse } from "@/app/api/v3/lib/response";
import type { TV3AuditLog, TV3Authentication } from "@/app/api/v3/lib/types";
import { assertCan } from "@/lib/authorization";
import { getApiKey } from "@/lib/apiKey/service";
import { rotateApiKey } from "@/modules/organization/settings/api-keys/lib/api-key";
import { assertCanGrantOrganizationAccess } from "@/modules/organization/settings/api-keys/lib/organization-access";

const FORBIDDEN_DETAIL = "You are not authorized to access this resource";

/**
 * The organization is resolved from the key itself, never from the caller, and an unknown key answers
 * 403 rather than 404 so key ids cannot be probed. The authorization matches the update and delete
 * actions (`apiKey.manage`), plus the organization-access floor: rotating hands the caller the secret
 * of a key that may carry `accessControl.write`, which is the same authority creating one would grant.
 */
export async function rotateV3ApiKey(params: {
  authentication: TV3Authentication;
  apiKeyId: string;
  auditLog?: TV3AuditLog;
  requestId: string;
  instance?: string;
}): Promise<Response> {
  const { authentication, apiKeyId, auditLog, requestId, instance } = params;

  const userId = getV3SessionUserId(authentication);
  if (!userId) return problemUnauthorized(requestId, "Session required", instance);

  try {
    const existing = await getApiKey(apiKeyId);
    if (!existing) throw new ResourceNotFoundError("apiKey", apiKeyId);

    await assertCan({ type: "user", id: userId }, "apiKey.manage", { type: "apiKey", id: apiKeyId });
    await assertCanGrantOrganizationAccess(userId, existing.organizationId, existing.organizationAccess);

    if (auditLog) {
      auditLog.organizationId = existing.organizationId;
      auditLog.targetId = apiKeyId;
    }

    const rotated = await rotateApiKey(apiKeyId);

    return successResponse(
      {
        id: rotated.id,
        label: rotated.label,
        createdAt: rotated.createdAt.toISOString(),
        lastUsedAt: null,
        organizationAccess: rotated.organizationAccess,
        apiKeyWorkspaces: rotated.apiKeyWorkspaces,
        key: rotated.actualKey,
      },
      { requestId }
    );
  } catch (error) {
    if (
      error instanceof ResourceNotFoundError ||
      error instanceof AuthorizationError ||
      error instanceof OperationNotAllowedError
    ) {
      return problemForbidden(requestId, FORBIDDEN_DETAIL, instance);
    }
    throw error;
  }
}
EOF
grep -rn "export const getApiKey\b" lib | head; grep -n "no-store\|Cache-Control" app/api/v3/lib/response.ts | head -5
